// lesen.mjs – ES-Modul, starten mit: node lesen.mjs
import { readFile } from 'node:fs/promises';

try {
  const inhalt = await readFile('daten.txt', 'utf8');
  console.log('Datei gelesen, Länge:', inhalt.length);
} catch (err) {
  console.error('Fehler beim Lesen:', err.message);
}

// readFile liefert hier ein Promise statt einen Callback zu erwarten.
// await wartet auf das Ergebnis, ohne node.js zu blockieren.
// Fehler kommen als Exception und landen im catch-Block.

// server.js – starten mit: node server.js
const http = require('node:http');

const server = http.createServer((req, res) => {
  if (req.method === 'GET' && req.url === '/api/hallo') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ text: 'Hallo von node.js' }));
  } else {
    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Nicht gefunden');
  }
});

server.listen(6061, '127.0.0.1', () => {
  console.log('Server läuft auf http://127.0.0.1:6061');
});

const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.join(__dirname, 'static-content');
const TYPES = { '.html': 'text/html', '.css': 'text/css',
                '.js': 'text/javascript' };
http.createServer((req, res) => {
  const name = path.basename(req.url) || 'index.html'; // kein ../ möglich
  const datei = path.join(ROOT, name);
  const typ = TYPES[path.extname(datei)] ?? 'text/plain';

  const stream = fs.createReadStream(datei);
  stream.on('open', () => res.writeHead(200, { 'Content-Type': typ }));
  stream.on('error', () => { res.writeHead(404); res.end(); });
  stream.pipe(res);
}).listen(6061, '127.0.0.1');

